package br.com.rotas.integration;
import br.com.rotas.config.AppProperties;import br.com.rotas.domain.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import javax.net.ssl.*;import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class ExternalServicesTest {
  AppProperties props(long interval){return new AppProperties(new AppProperties.Store("S","S","S",-23.61,-46.64),new AppProperties.Region(-23.72,-23.55,-46.75,-46.58,"x",List.of()),new AppProperties.External(new AppProperties.External.Nominatim("http://test","academic-test",2,interval),new AppProperties.External.Osrm("http://test",2),new AppProperties.External.Overpass("http://test",2)),true,AppProperties.GraphGeneration.defaults());}
  @Test void metersToKilometers(){assertEquals(1.234,RouteData.metersToKilometers(1234));}
  @Test void geocodingMapsAndCaches(){var http=new StubClient("[{\"display_name\":\"Rua A, São Paulo\",\"lat\":\"-23.61\",\"lon\":\"-46.64\",\"address\":{\"road\":\"Rua A\",\"house_number\":\"10\",\"suburb\":\"Saúde\",\"city\":\"São Paulo\",\"state\":\"SP\",\"postcode\":\"04000\"}}]",200);var s=new GeocodingService(props(0),new ObjectMapper(),http);assertEquals("Rua A",s.search(" Rua   A ").getFirst().road());s.search("rua a");assertEquals(1,http.calls.size());assertEquals(1,s.cacheSize());}
  @Test void geocodingRespectsMinimumInterval(){var http=new StubClient("[{\"display_name\":\"X\",\"lat\":\"-23.61\",\"lon\":\"-46.64\",\"address\":{}}]",200);var s=new GeocodingService(props(120),new ObjectMapper(),http);s.search("A");s.search("B");assertTrue(http.calls.get(1)-http.calls.get(0)>=90);}
  @Test void broadGeocodingAllowsOriginOutsideFixedServiceArea(){var http=new StubClient("[{\"display_name\":\"Campinas, SP\",\"lat\":\"-22.90\",\"lon\":\"-47.06\",\"address\":{}}]",200);var s=new GeocodingService(props(0),new ObjectMapper(),http);assertEquals(-22.90,s.searchBroad("Campinas").getFirst().latitude());assertTrue(http.lastUri().contains("countrycodes=br"));assertFalse(http.lastUri().contains("bounded=1"));}
  @Test void routingConvertsGeometryAndCaches(){var http=new StubClient("{\"routes\":[{\"distance\":2500,\"duration\":300,\"geometry\":{\"coordinates\":[[-46.64,-23.61],[-46.65,-23.62]]}}]}",200);var s=new RoutingService(props(0),new ObjectMapper(),http);var a=p("A",-23.61,-46.64);var b=p("B",-23.62,-46.65);assertEquals(2.5,s.route(a,b,9).distanceKm());s.route(a,b,9);assertEquals(1,http.calls.size());}
  @Test void routingFallsBackOnFailureWithoutInventingRoadGeometry(){var s=new RoutingService(props(0),new ObjectMapper(),new StubClient("{}",503));var r=s.route(p("A",-23.61,-46.64),p("B",-23.62,-46.65),1.7);assertTrue(r.fallback());assertEquals(1.7,r.distanceKm());assertTrue(r.geometry().isEmpty(),"Uma reta entre vértices não pode ser apresentada como geometria viária");}
  @Test void routingBuildsDirectedDistanceTableInKilometers(){var http=new StubClient("{\"distances\":[[0,2500],[3100,0]]}",200);var s=new RoutingService(props(0),new ObjectMapper(),http);var table=s.distanceTable(List.of(p("A",-23.61,-46.64),p("B",-23.62,-46.65)));assertFalse(table.fallback());assertEquals(2.5,table.distancesKm()[0][1]);assertEquals(3.1,table.distancesKm()[1][0]);assertTrue(http.lastUri().contains("annotations=distance"));}
  @Test void routingTableReturnsRoadSnappedCoordinatesInTheSameRequest(){var http=new StubClient("{\"distances\":[[0,2500],[3100,0]],\"sources\":[{\"distance\":12,\"name\":\"Rua A\",\"location\":[-46.641,-23.611]},{\"distance\":18,\"name\":\"Rua B\",\"location\":[-46.651,-23.621]}]}",200);var s=new RoutingService(props(0),new ObjectMapper(),http);var table=s.snappedDistanceTable(List.of(p("A",-23.61,-46.64),p("B",-23.62,-46.65)));assertFalse(table.fallback());assertEquals(-23.611,table.snappedPoints().getFirst().latitude());assertEquals("Rua B",table.snappedPoints().getLast().roadName());assertEquals(2.5,table.distancesKm()[0][1]);assertEquals(1,http.calls.size());}
  @Test void routingTablePreservesUnreachableCells(){var s=new RoutingService(props(0),new ObjectMapper(),new StubClient("{\"distances\":[[0,null],[1200,0]]}",200));var table=s.distanceTable(List.of(p("A",-23.61,-46.64),p("B",-23.62,-46.65)));assertTrue(Double.isInfinite(table.distancesKm()[0][1]));assertEquals(1.2,table.distancesKm()[1][0]);}
  @Test void routingSnapsOriginToDrivableNetwork(){var http=new StubClient("{\"waypoints\":[{\"distance\":18.4,\"name\":\"Avenida Teste\",\"location\":[-46.641,-23.611]}]}",200);var s=new RoutingService(props(0),new ObjectMapper(),http);var snap=s.snap(p("A",-23.61,-46.64));assertFalse(snap.fallback());assertEquals(-23.611,snap.latitude());assertEquals(-46.641,snap.longitude());assertEquals("Avenida Teste",snap.roadName());}
  private Point p(String id,double lat,double lon){return new Point(id,id,id,lat,lon,PointType.INTERMEDIATE);}
  static class StubClient extends HttpClient {final String body;final int status;final List<Long> calls=new ArrayList<>();final List<URI> uris=new ArrayList<>();StubClient(String b,int s){body=b;status=s;}public <T> HttpResponse<T> send(HttpRequest request,HttpResponse.BodyHandler<T> handler){calls.add(System.currentTimeMillis());uris.add(request.uri());@SuppressWarnings("unchecked")T cast=(T)body;return new StubResponse<>(request,status,cast);}String lastUri(){return uris.getLast().toString();}public <T> CompletableFuture<HttpResponse<T>> sendAsync(HttpRequest r,HttpResponse.BodyHandler<T> h){return CompletableFuture.completedFuture(send(r,h));}public <T> CompletableFuture<HttpResponse<T>> sendAsync(HttpRequest r,HttpResponse.BodyHandler<T> h,HttpResponse.PushPromiseHandler<T> p){return sendAsync(r,h);}public Optional<CookieHandler> cookieHandler(){return Optional.empty();}public Optional<Duration> connectTimeout(){return Optional.of(Duration.ofSeconds(1));}public Redirect followRedirects(){return Redirect.NEVER;}public Optional<ProxySelector> proxy(){return Optional.empty();}public SSLContext sslContext(){try{return SSLContext.getDefault();}catch(Exception e){throw new RuntimeException(e);}}public SSLParameters sslParameters(){return new SSLParameters();}public Optional<Authenticator> authenticator(){return Optional.empty();}public Version version(){return Version.HTTP_1_1;}public Optional<java.util.concurrent.Executor> executor(){return Optional.empty();}}
  record StubResponse<T>(HttpRequest request,int statusCode,T body) implements HttpResponse<T>{public Optional<HttpResponse<T>> previousResponse(){return Optional.empty();}public HttpHeaders headers(){return HttpHeaders.of(Map.of(),(a,b)->true);}public Optional<SSLSession> sslSession(){return Optional.empty();}public URI uri(){return request.uri();}public HttpClient.Version version(){return HttpClient.Version.HTTP_1_1;}}
}
